import inspect
import logging
import os
from contextlib import contextmanager

import six
import yaml

from .exceptions import ConfigurationFileNotFound, MultipleConfigurationsDefined, AbstractLibConfigError
from .singleton import Singleton
from .ute_config_loader import is_iphy


# TODO it is possible to define configuration test suite level (in .robot file) shall we clear configuration when suite ends


@contextmanager
def read_configfile(config_file_path):
    """
    Context manager that reads content of configuration file into string.

    :param config_file_path: location of configuration file
    :return: configuration file content as string
    """
    with open(config_file_path, 'r') as config_file:
        content = config_file.read()
        yield content


@six.add_metaclass(Singleton)
class Config:
    """
    Find and read testline configuration.
    Store the configuration the found and path to configuration.
    """
    def __init__(self, abstract_lib_config=None):
        """
        Finds and Reads the content of the Abstract lib configuration. Seaching order:
        1. abstract_lib_config constructor parameter. It might be either string with path
           to config file or dict describing config
        2. From ABSTRACT_LIB_CONFIG environment variable. only path to config file allowed
        3. Backward compatibility: From TA/UTE_UE_CONFIG environment variable. only path to
           config file allowed
        4. Raises MultipleConfigurationsDefined when abstract_lib_config is None and both
           ABSTRACT_LIB_CONFIG and TA/UTE_UE_CONFIG environment variables are defined

        :param abstract_lib_config: given path to AL config. e.g. config path from Robot.
        :raises: :py:class: `ute_common_abstract_core.exceptions.MultipleConfigurationsDefined`: when both ABSTRACT_LIB_CONFIG and TA/UTE_UE_CONFIG
                                                                                             environment variables are defined
        """
        self.logger = logging.getLogger('al.config')

        # Takes code location of caller of this function caller (means caller of Singleton)
        (_, pathname, lineno, func_name, _, _) = inspect.stack(0)[2]
        constructor_param = "abstract_lib_config" if abstract_lib_config else ""
        call_msg = f"Config({constructor_param}) instance creation called by {func_name}() [{pathname}:{lineno}]"
        self.logger.debug(call_msg)
        self._config = None
        self._config_path = None
        self._default_config_dir = None

        if abstract_lib_config:
            self.logger.debug(f"config passed directly: abstract_lib_config == {str(abstract_lib_config)}")
            self._read_config_from_file_or_dict(abstract_lib_config)
        elif self._exctact_env_variable_name():
            self._update_config_from_environment_variable()
        elif is_iphy(self.logger):
            self.logger.debug("iphy tl detected")
            self._read_config_from_file_or_dict({'UE_POOLS': {'IphyUePoolDynamic': {}}})  # TODO: read below
            # TODO: to be changed in the future: given dict belongs to ta_ue scope
        else:
            self.logger.warning("config set to None !!!")  # we can see empty configuration in log
            self._config = None
        # TODO should we fail empty configuration !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!

    def _is_env_variable_defined(self, variable_name):
        return variable_name in os.environ and os.environ[variable_name]

    def _exctact_env_variable_name(self):
        if self._is_env_variable_defined('ABSTRACT_LIB_CONFIG') and (self._is_env_variable_defined('TA_UE_CONFIG')
                                                                     or self._is_env_variable_defined('TA_UE_CONFIG')):
            err_msg = "Detected both 'ABSTRACT_LIB_CONFIG' and legacy 'TA/UTE_UE_CONFIG' environment variables. " + \
                      "Please define only one"
            self.logger.error(f"MultipleConfigurationsDefined({err_msg})")
            raise MultipleConfigurationsDefined(err_msg)
        if self._is_env_variable_defined('ABSTRACT_LIB_CONFIG'):
            return 'ABSTRACT_LIB_CONFIG'
        if self._is_env_variable_defined('TA_UE_CONFIG'):
            return 'TA_UE_CONFIG'
        if self._is_env_variable_defined('UTE_UE_CONFIG'):
            return 'UTE_UE_CONFIG'
        return None

    def _update_config_from_environment_variable(self):
        variable_name = self._exctact_env_variable_name()
        if variable_name:
            config_path = os.environ[variable_name]
            self.logger.debug(f"updating config from env variable {variable_name}: {config_path}")
            self._check_config_path(config_path, "%s environment variable" % variable_name)
            self._config = self._read_configuration_from_file(config_path)

    def _read_config_from_file_or_dict(self, abstract_lib_config):
        try:
            if isinstance(abstract_lib_config, dict):
                self._config = abstract_lib_config
                self.logger.debug(f"config set from dict: {abstract_lib_config}")
            elif isinstance(eval(abstract_lib_config), dict):  # pylint: disable=eval-used
                self._config = eval(abstract_lib_config)  # pylint: disable=eval-used
                self.logger.debug(f"config set from dict: {self._config}")
            else:
                err_msg = 'ABSTRACT_LIB_CONFIG is neither a file path nor a dict'
                self.logger.error(f"AbstractLibConfigError({err_msg})")
                raise AbstractLibConfigError(err_msg)
        except (SyntaxError, NameError):
            self._check_config_path(abstract_lib_config, "abstract_lib_config constructor parameter")
            self._config = self._read_configuration_from_file(abstract_lib_config)

    def _read_configuration_from_file(self, config_path):
        self._config_path = os.path.abspath(config_path)
        self._default_config_dir = os.path.dirname(self._config_path)
        return self.read_yaml_configfile(self._config_path)

    def _initialize_config(self):
        if self._config is None:
            self.logger.debug("config initialized: None --> {}")
            self._config = {}

    def _check_config_path(self, config_path, defined_in):
        if not os.path.isfile(config_path):
            err_msg = f'File defined in {defined_in} does not exist: {config_path}'
            self.logger.error(f"ConfigurationFileNotFound({err_msg})")
            raise ConfigurationFileNotFound(err_msg)

    def get_config_path(self):
        """
        Returns the path to config file.

        :return: path to config file
        """
        return self._config_path

    def get_default_config_dir(self):
        """
        Return the default config dir that is same as directory of config file.

        :return: default config dir
        """
        return self._default_config_dir

    def get_config(self, section=None):
        """
        Retrieves library configuration.
        :param section: section from configuration file e.g. UE_POOLS
        :return: configuration as dict
        """
        # Takes code location of caller of this function
        (_, pathname, lineno, func_name, _, _) = inspect.stack(0)[1]
        constructor_param = f"section={section}" if section else ""
        call_msg = f"{func_name}() calls get_config({constructor_param})  [{pathname}:{lineno}]"
        self.logger.debug(call_msg)
        if section:
            try:
                config_section = self._config[section]
                self.logger.debug(f"get_config(section={section}) == {config_section}")
                return config_section
            except (KeyError, TypeError):
                self.logger.warning("get_config() == None !!!")
                return None
                # raise EmptyConfigSection("Cannot find {} section in configuration. Please define it".format(section))
        else:
            self.logger.debug(f"get_config() == {self._config}")
            return self._config

    def resolve_config_abspath(self, config):
        """
        Resolve full path to given config file.

        Search order:
          1. path in given config parameter
          2. default config dir + path given in config parameter

        :param config:
        :return:
        """
        if os.path.isfile(config):
            return os.path.abspath(config)
        if self._default_config_dir and os.path.isfile(os.path.join(self._default_config_dir, config)):
            return os.path.abspath(os.path.join(self._default_config_dir, config))
        # raise ConfigurationFileNotFound('Config file does not exist: {}'.format(config))
        return None

    def read_yaml_configfile(self, config_file_path):
        """
        Read and convert YAML into dictionary.

        :param config_file_path: location of yaml file
        :return: configuration as a python dictionary
        """
        with read_configfile(config_file_path) as content:
            self.logger.debug(f"configfile {config_file_path} read:\n{content}")
            return self.convert_yaml_to_dict(content)

    @staticmethod
    def convert_yaml_to_dict(yaml_string):
        """
        Convert YAML string into dictionary.

        :param yaml_string: YAML formatted string
        :return: python dictionary
        """
        return yaml.load(stream=yaml_string, Loader=yaml.FullLoader)
